<script>
  import { splitObject } from '@splendidlabz/utils'
  import {
    hasAccessibleName,
    markActiveAnchorIn,
    scrollToElement,
  } from '@splendidlabz/utils/dom'
  import { init } from '../../../utils/index.js'
  import {
    TRANSITION_OPT_KEYS,
    applyTransition,
  } from '../../../utils/transitions.js'
  import Portal from '../../Portal.svelte'
  import {
    DISCLOSURE_CONTENT_OPT_KEYS,
    disclosureContent,
    getDisclosure,
  } from './disclosure.svelte.js'

  let {
    ref = $bindable(null),
    class: klass,
    id,
    role = 'dialog',
    'aria-label': ariaLabel,
    'aria-labelledBy': ariaLabelledBy,
    'aria-describedby': ariaDescribedBy,
    componentName = 'DisclosureContent',
    portal = true,
    scrollToAnchor = false,

    // Slots
    children,
    ...remainingProps
  } = $props()

  const disclosureSplit = $derived(
    splitObject(remainingProps, DISCLOSURE_CONTENT_OPT_KEYS),
  )
  const disclosureContentOpts = $derived(disclosureSplit.picked)
  const transitionSplit = $derived(
    splitObject(disclosureSplit.omitted, TRANSITION_OPT_KEYS),
  )
  const transitionOpts = $derived(transitionSplit.picked)
  const remaining = $derived(transitionSplit.omitted)

  init(() => {
    if (!id) throw new Error(`${componentName} requires an id`)
    // Accessible name warning
    if (role === 'dialog' && !hasAccessibleName(ariaLabel, ariaLabelledBy)) {
      console.warn(
        `DrawerContent (with id: ${id}) is a dialog and should have an accessible name. Please create one with aria-label or aria-labelledby.`,
      )
    }
  })

  let d = $derived(getDisclosure(id))
  let show = $derived(d?.state.show)

  $effect(_ => {
    if (show && ref && scrollToAnchor) {
      const anchor = markActiveAnchorIn(ref)
      scrollToElement(anchor)
    }
  })
</script>

<!-- Snippets -->
{#snippet dc()}
  <div
    {...remaining}
    bind:this={ref}
    {id}
    class="disclosure-content {klass}"
    aria-describedby={ariaDescribedBy}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledBy}
    {role}
    use:disclosureContent={{ options: disclosureContentOpts }}
    transition:applyTransition|global={transitionOpts}
  >
    {#if children}
      {@render children()}
    {/if}
  </div>
{/snippet}

<!-- Render -->
{#if show}
  {#if portal}
    <Portal>{@render dc()}</Portal>
  {:else}
    {@render dc()}
  {/if}
{/if}
